vehicle_access = self.env['fleet.vehicle'].has_access('read') log_contract_access = self.env['fleet.vehicle.log.contract'].has_access('read')
if vehicle_access and log_contract_access: self.env.cr.execute(""" SELECT v.id FROM fleet_vehicle v WHERE v.driver_employee_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM fleet_vehicle_log_contract c WHERE c.vehicle_id = v.id AND c.company_id = v.company_id AND c.active IS TRUE AND c.state = 'open') AND v.company_id IN %s AND v.active IS TRUE GROUP BY v.id """, (tuple(self.env.companies.ids), )) vehicles_no_contract = [vid[0] for vid in self.env.cr.fetchall()]
if vehicles_no_contract: warning_records = self.env['fleet.vehicle'].browse(vehicles_no_contract)
